const s = $input.first().json;
const q = s.action_queue || [];
const f = s.financials || {};
const money = q.reduce((a, x) => a + (x.value || 0), 0);
const lines = q.slice(0, 15).map(a => `• [${a.kind}] ${a.title}` + (a.value ? ` ($${a.value.toLocaleString()})` : ''));
const text = `*Wholesale Ops — ${q.length} action(s) need you*\n` +
  `Revenue: $${(f.revenue||0).toLocaleString()} · Active: ${f.active||0} · Pipeline fee value: $${(f.pipeline_fee_value||0).toLocaleString()}\n` +
  `Potential in queue: $${money.toLocaleString()}\n\n` +
  (lines.join('\n') || 'Nothing needs you — agents are working.') +
  `\n\nOpen the cockpit to approve/send: http://HOST:8200/`;
return [{ json: { text, count: q.length } }];
